function lexicographicallySmallestString(s) {
  const n = s.length;
  const linked = (a, b) => {
    const gap = Math.abs(s.charCodeAt(a) - s.charCodeAt(b));
    return gap === 1 || gap === 25;
  };
  const removable = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(false));
  for (let i = 0; i <= n; i++) {
    removable[i][i] = true;
  }
  for (let length = 2; length <= n; length += 2) {
    for (let i = 0; i + length <= n; i++) {
      const j = i + length;
      for (let k = i + 1; k < j; k += 2) {
        if (linked(i, k) && removable[i + 1][k] && removable[k + 1][j]) {
          removable[i][j] = true;
          break;
        }
      }
    }
  }
  const best = new Array(n + 1).fill('');
  for (let i = n - 1; i >= 0; i--) {
    best[i] = s[i] + best[i + 1];
    for (let j = i + 2; j <= n; j += 2) {
      if (removable[i][j] && best[j] < best[i]) {
        best[i] = best[j];
      }
    }
  }
  return best[0];
}

