function lexicographicallySmallestString(s) {
  // Explore every string reachable by deletions and keep the smallest one seen.
  const seen = new Set([s]);
  const stack = [s];
  let smallest = s;
  while (stack.length > 0) {
    const current = stack.pop();
    if (current < smallest) smallest = current;
    for (let p = 0; p + 1 < current.length; p++) {
      const gap = Math.abs(current.charCodeAt(p) - current.charCodeAt(p + 1));
      if (gap !== 1 && gap !== 25) continue;
      const next = current.slice(0, p) + current.slice(p + 2);
      if (!seen.has(next)) {
        seen.add(next);
        stack.push(next);
      }
    }
  }
  return smallest;
}

