function generate(rand, size) {
  // Letters from a narrow window of the circular alphabet are often neighbours, so many deletions are possible.
  const n = size === 'large' ? 220 + Math.floor(rand() * 31) : 1 + Math.floor(rand() * 12);
  const base = Math.floor(rand() * 26);
  const width = rand() < 0.15 ? 26 : 2 + Math.floor(rand() * 3);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + (base + Math.floor(rand() * width)) % 26);
  return [s];
}
